alter table public.platform_owner_records drop constraint if exists platform_owner_records_status_check;
alter table public.platform_owner_records add constraint platform_owner_records_status_check check(status in('invited','active','suspended','inactive'));
create or replace function public.accept_platform_owner_invitation(p_token uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_invite public.platform_owner_invitations%rowtype;v_email text;v_conference_id uuid;v_slug text;begin select * into v_invite from public.platform_owner_invitations where token=p_token for update;if v_invite.id is null or v_invite.accepted_at is not null or v_invite.expires_at<now() then raise exception 'This owner invitation is no longer available.';end if;v_email:=lower(coalesce(auth.jwt()->>'email',''));if v_email='' or v_email<>lower(v_invite.email) then raise exception 'Sign in with the email address that received this invitation.';end if;v_slug:=lower(regexp_replace(v_invite.conference_name,'[^a-zA-Z0-9]+','-','g'))||'-'||substr(replace(gen_random_uuid()::text,'-',''),1,8);insert into public.conferences(name,slug) values(v_invite.conference_name,v_slug) returning id into v_conference_id;insert into public.conference_subscriptions(conference_id,status,due_on) values(v_conference_id,'due',date_trunc('month',current_date)::date) on conflict do nothing;update public.platform_owner_invitations set accepted_at=now(),accepted_by=(select auth.uid()) where id=v_invite.id;update public.platform_owner_records set conference_id=v_conference_id,profile_id=(select auth.uid()),status='invited',updated_at=now() where id=v_invite.owner_record_id;return v_conference_id;end;$$;
create or replace function public.platform_set_owner_status(p_owner_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$ declare r public.platform_owner_records%rowtype;begin if not public.is_platform_creator() then raise exception 'Platform Creator access is required.';end if;if p_status not in('active','suspended','inactive') then raise exception 'Choose Active, Suspended, or Inactive.';end if;select * into r from public.platform_owner_records where id=p_owner_id for update;if r.id is null then raise exception 'Owner was not found.';end if;if p_status='active' then if r.profile_id is null or r.conference_id is null or not exists(select 1 from public.platform_owner_contract_acknowledgments where owner_record_id=r.id) then raise exception 'The owner must accept the invitation and sign the contract first.';end if;insert into public.conference_memberships(conference_id,profile_id,role) values(r.conference_id,r.profile_id,'owner') on conflict do nothing;else delete from public.conference_memberships where conference_id=r.conference_id and profile_id=r.profile_id and role='owner';end if;update public.platform_owner_records set status=p_status,updated_at=now() where id=p_owner_id;end;$$;
revoke all on function public.accept_platform_owner_invitation(uuid),public.platform_set_owner_status(uuid,text) from public;grant execute on function public.accept_platform_owner_invitation(uuid),public.platform_set_owner_status(uuid,text) to authenticated;
